    protected RealMatrix createRealMatrix(double[] data, int nRows, int nCols) {
        double[][] matrixData = new double[nRows][nCols];
        int ptr = 0;
        for (int i = 0; i < nRows; i++) {
            System.arraycopy(data, ptr, matrixData[i], 0, nCols);
            ptr += nCols;
        }
        return new Array2DRowRealMatrix(matrixData);
    }

    /**
     * Verifies that covariance matrix entries match the corresponding variance
     * and pairwise covariance computations.
     */
    @Test
    public void testConsistency() {
        final RealMatrix matrix = createRealMatrix(swissData, SWISS_ROW_COUNT, SWISS_COLUMN_COUNT);
        final RealMatrix covarianceMatrix = new Covariance(matrix).getCovarianceMatrix();

        assertDiagonalMatchesColumnVariances(matrix, covarianceMatrix);
        assertPairwiseCovarianceIsConsistent(matrix, covarianceMatrix);
        assertRepeatedColumnsShareTheSourceColumnVariance(matrix);
        assertBiasCorrectionDefaults(matrix, covarianceMatrix);
    }

    private void assertDiagonalMatchesColumnVariances(RealMatrix matrix, RealMatrix covarianceMatrix) {
        for (int i = 0; i < SWISS_COLUMN_COUNT; i++) {
            Assert.assertEquals(
                org.apache.commons.statistics.descriptive.Variance.of(matrix.getColumn(i)).getAsDouble(),
                covarianceMatrix.getEntry(i, i),
                DEFAULT_TOLERANCE);
        }
    }

    private void assertPairwiseCovarianceIsConsistent(RealMatrix matrix, RealMatrix covarianceMatrix) {
        Assert.assertEquals(
            covarianceMatrix.getEntry(2, 3),
            new Covariance().covariance(matrix.getColumn(2), matrix.getColumn(3), true),
            DEFAULT_TOLERANCE);
        Assert.assertEquals(
            covarianceMatrix.getEntry(2, 3),
            covarianceMatrix.getEntry(3, 2),
            EXACT_TOLERANCE);
    }

    private void assertRepeatedColumnsShareTheSourceColumnVariance(RealMatrix matrix) {
        RealMatrix repeatedColumns = new Array2DRowRealMatrix(SWISS_ROW_COUNT, REPEATED_COLUMN_COUNT);
        for (int i = 0; i < REPEATED_COLUMN_COUNT; i++) {
            repeatedColumns.setColumnMatrix(i, matrix.getColumnMatrix(0));
        }

        RealMatrix repeatedCovarianceMatrix = new Covariance(repeatedColumns).getCovarianceMatrix();
        double columnVariance =
            org.apache.commons.statistics.descriptive.Variance.of(matrix.getColumn(0)).getAsDouble();

        for (int i = 0; i < REPEATED_COLUMN_COUNT; i++) {
            for (int j = 0; j < REPEATED_COLUMN_COUNT; j++) {
                Assert.assertEquals(columnVariance, repeatedCovarianceMatrix.getEntry(i, j), DEFAULT_TOLERANCE);
            }
        }
    }

    private void assertBiasCorrectionDefaults(RealMatrix matrix, RealMatrix covarianceMatrix) {
        double[][] data = matrix.getData();
        TestUtils.assertEquals(
            "Covariances",
            covarianceMatrix,
            new Covariance().computeCovarianceMatrix(data),
            EXACT_TOLERANCE);
        TestUtils.assertEquals(
            "Covariances",
            covarianceMatrix,
            new Covariance().computeCovarianceMatrix(data, true),
            EXACT_TOLERANCE);

        double[] x = data[0];
        double[] y = data[1];
        Assert.assertEquals(
            new Covariance().covariance(x, y),
            new Covariance().covariance(x, y, true),
            EXACT_TOLERANCE);
    }
